// @ts-check
/**
 * The card catalog shipped with the app (cardcatalog.json, generated by
 * tools/cards/build-catalog.mjs), parsed. Kept apart from cards.js so that the offline tools that
 * write the catalog never load it.
 */
import catalogJson from './cardcatalog.json' with { type: 'json' };
import { parseCatalog } from './cards.js';

/** @typedef {import('./cards.js').Catalog} Catalog */

const shipped = parseCatalog(/** @type {unknown} */ (catalogJson));
if (!shipped.ok) throw new Error(`the shipped card catalog does not parse: ${shipped.error}`);
/** @type {Catalog} */
export const CATALOG = shipped.catalog;
